window.ScripturaLexicons.BDAG_PART_0366 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0366-01\" data-source=\"BDAG\" data-search=\"ὑετός, οῦ, ὁ substantivo masculino chuva BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὑετός, οῦ, ὁ</td><td>substantivo masculino</td><td>chuva</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0366-02\" data-source=\"BDAG\" data-search=\"υἱοθεσία, ας, ἡ substantivo feminino adoção; filiação BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">υἱοθεσία, ας, ἡ</td><td>substantivo feminino</td><td>adoção; filiação</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0366-03\" data-source=\"BDAG\" data-search=\"υἱός, οῦ, ὁ substantivo masculino filho; descendente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">υἱός, οῦ, ὁ</td><td>substantivo masculino</td><td>filho; descendente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0366-04\" data-source=\"BDAG\" data-search=\"ὕλη, ης, ἡ substantivo feminino floresta; madeira; matéria BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὕλη, ης, ἡ</td><td>substantivo feminino</td><td>floresta; madeira; matéria</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0366-05\" data-source=\"BDAG\" data-search=\"ὑμεῖς pronome pessoal vós; remissão a σύ BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὑμεῖς</td><td>pronome pessoal</td><td>vós; remissão a σύ</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0366-06\" data-source=\"BDAG\" data-search=\"Ὑμέναιος, ου, ὁ nome próprio masculino Himeneu BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ὑμέναιος, ου, ὁ</td><td>nome próprio masculino</td><td>Himeneu</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0366-07\" data-source=\"BDAG\" data-search=\"ὑμέτερος, α, ον pronome adjetival possessivo vosso BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὑμέτερος, α, ον</td><td>pronome adjetival possessivo</td><td>vosso</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0366-08\" data-source=\"BDAG\" data-search=\"ὑμνέω verbo cantar; cantar louvores BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὑμνέω</td><td>verbo</td><td>cantar; cantar louvores</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0366-09\" data-source=\"BDAG\" data-search=\"ὕμνος, ου, ὁ substantivo masculino hino; cântico de louvor BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὕμνος, ου, ὁ</td><td>substantivo masculino</td><td>hino; cântico de louvor</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0366-10\" data-source=\"BDAG\" data-search=\"ὑπάγω verbo ir; retirar-se; partir; morrer BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὑπάγω</td><td>verbo</td><td>ir; retirar-se; partir; morrer</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0366-11\" data-source=\"BDAG\" data-search=\"ὑπακοή, ῆς, ἡ substantivo feminino obediência; resposta BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὑπακοή, ῆς, ἡ</td><td>substantivo feminino</td><td>obediência; resposta</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0366-12\" data-source=\"BDAG\" data-search=\"ὑπακούω verbo obedecer; ouvir; atender BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὑπακούω</td><td>verbo</td><td>obedecer; ouvir; atender</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0366-13\" data-source=\"BDAG\" data-search=\"ὑπαλείφω verbo ungir BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὑπαλείφω</td><td>verbo</td><td>ungir</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0366-14\" data-source=\"BDAG\" data-search=\"ὕπανδρος, ον adjetivo casada; sujeita a marido BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὕπανδρος, ον</td><td>adjetivo</td><td>casada; sujeita a marido</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0366-15\" data-source=\"BDAG\" data-search=\"ὑπαντάω verbo ir ao encontro; encontrar; opor-se BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὑπαντάω</td><td>verbo</td><td>ir ao encontro; encontrar; opor-se</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0366-16\" data-source=\"BDAG\" data-search=\"ὑπάντησις, εως, ἡ substantivo feminino encontro BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὑπάντησις, εως, ἡ</td><td>substantivo feminino</td><td>encontro</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0366-17\" data-source=\"BDAG\" data-search=\"ὕπαρξις, εως, ἡ substantivo feminino existência; propriedade; bens BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὕπαρξις, εως, ἡ</td><td>substantivo feminino</td><td>existência; propriedade; bens</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0366-18\" data-source=\"BDAG\" data-search=\"ὑπάρχω verbo existir; estar; ser; possuir BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὑπάρχω</td><td>verbo</td><td>existir; estar; ser; possuir</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0366-19\" data-source=\"BDAG\" data-search=\"ὑπέβαλον forma verbal remissão a ὑποβάλλω BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὑπέβαλον</td><td>forma verbal</td><td>remissão a ὑποβάλλω</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0366-20\" data-source=\"BDAG\" data-search=\"ὑπέδειξα forma verbal remissão a ὑποδείκνυμι BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὑπέδειξα</td><td>forma verbal</td><td>remissão a ὑποδείκνυμι</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0366-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑετός, οῦ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὑετός</span>, <span class=\"greek\">οῦ</span>, <span class=\"greek\">ὁ</span> (Hom.+; PPetr II, 49a, 13 [III a.C.]; LXX; ApcEsdr 2:28 p. 26, 23 Tdf.; Philo; Jos., Ant. 8, 106; 18, 285; SibOr 3, 690) chuva <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.14.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 14:17</a>; 28:2; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.6.7\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 6:7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.7\" target=\"_blank\" rel=\"noopener noreferrer\">Js 5:7</a> v.l., 18; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.11.6\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 11:6</a>.—B. 68. DELG s.v. <span class=\"greek\">ὕω</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0366-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">υἱοθεσία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">υἱοθεσία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">υἱός</span>, <span class=\"greek\">θέσις</span> ‘colocação’; Diod S 31, 27, 2 ed. Dind. X 31, 13; Diog. L. 4, 53. Frequente em inscr. [SIG índice; Dssm., NB 66f=BS 239; Rouffiac 47]; papiros [PLips 28, 14; 17; 22 al.; POxy 1206, 8; 14 al., ambos do IV d.C.; cf. Diod S 4, 39, 2 <span class=\"greek\">ποιεῖν</span> <span class=\"greek\">θετὸν</span> <span class=\"greek\">υἱον</span>; Preisigke, Fachwörter 1915; Jur. Pap., introd. ao n.º 10 p. 22]) adoção, lit. termo técnico jurídico de ‘adoção’ de crianças, em nossa literatura, isto é, em Paulo, somente em sentido transferido de uma relação filial transcendente entre Deus e seres humanos (com o aspecto jurídico, não a especificidade de gênero, como componente semântico principal)</p><p class=\"entry-text\"><span class=\"sense-number\">ⓐ</span> da aceitação da nação de Israel como filho de Deus (cf. Ex 4:22; Is 1:2 al., onde, contudo, falta a palavra <span class=\"greek\">υἱοθ</span>.; não se encontra em parte alguma da LXX) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 9:4</a>.</p><p class=\"entry-text\"><span class=\"sense-number\">ⓑ</span> dos que creem em Cristo e são aceitos por Deus como filhos de Deus (Iren. 5, 12, 2 [Harv. II 351, 2]) com plenos direitos <span class=\"greek\">τὴν</span> <span class=\"greek\">υἱοθεσίαν</span> <span class=\"greek\">ἀπολαβεῖν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.5\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 4:5</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 1:5</a>. <span class=\"greek\">ἡ</span> <span class=\"greek\">δι</span>’ <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">διδομένη</span> <span class=\"greek\">υἱοθεσία</span> AcPl Ha 2, 28 (v. aparato). O Espírito, que os convertidos recebem, atua como <span class=\"greek\">πνεῦμα</span> <span class=\"greek\">υἱοθεσίας</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 8:15</a> (op. <span class=\"greek\">πν</span>. <span class=\"greek\">δουλείας</span>=um espírito tal como o possuído por um escravo, não pelo filho da casa). Os crentes entram no pleno gozo de sua <span class=\"greek\">υἱοθεσία</span> somente quando o tempo do cumprimento os liberta do corpo terreno v. 23.—Harnack (v. <span class=\"greek\">παλιγγενεσία</span> 2); TWhaling, Adoption: PTR 21, 1923, 223–35; AWentzel, Her 65, 1930, 167–76; ADieterich, Eine Mithrasliturgie 1903, 134–56; LMarshall, Challenge of NT Ethics ’47, 258f; WRossell, JBL 71, ’52, 233f; DTheron, EvQ 28, ’56, 6–14; JScott, Adoption as Sons of God ’92. V. Lampe s.v. <span class=\"greek\">υἱοθετέω</span>.—New Docs 3, 17; 4, 173. DELG s.v. <span class=\"greek\">υἱός</span>. M-M. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0366-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">υἱός, οῦ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">υἱός</span>, <span class=\"greek\">οῦ</span>, <span class=\"greek\">ὁ</span> (Hom.+; empréstimo no rabínico) primariamente ‘filho’</p><p class=\"entry-text\"><span class=\"sense-number\">①</span> indivíduo do sexo masculino que se encontra em relação de parentesco, quer biologicamente, quer por ato jurídico, filho, prole, descendente</p><p class=\"entry-text\"><span class=\"sense-number\">ⓐ</span> descendente masculino direto de uma pessoa, filho <span class=\"greek\">τέξεται</span> <span class=\"greek\">υἱόν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.1.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 1:21</a>; GJs 14:2 (cf. Mel., P. 8, 53 <span class=\"greek\">ὡς</span> <span class=\"greek\">γὰρ</span> <span class=\"greek\">υἱὸς</span> <span class=\"greek\">τεχθείς</span>). Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.1.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 1:23</a> (Is 7:14) e 25; 10:37 (com <span class=\"greek\">θυγάτηρ</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:6a</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:13</a>, 31, 57; 11:11; 15:11 (sobre isto JEngel, Die Parabel v. Verlorenen Sohn: ThGl 18, 1926, 54–64; MFrost, The Prodigal Son: Exp. 9th ser., 2, 1924, 56–60; EBuonaiuti, Religio 11, ’35, 398–402); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.29\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:29</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 9:9</a> (cf. Gen 18:10); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.22\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 4:22</a> al. Com gen. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:9</a>; 20:20f; 21:37ab; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:3</a>; 9:17; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.2\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:2</a>; 4:22; 15:19; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.9.19\" target=\"_blank\" rel=\"noopener noreferrer\">J 9:19f</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:21</a>; 16:1; 23:16; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.30\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 4:30abc</a> (Gen 21:10abc); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.2.21\" target=\"_blank\" rel=\"noopener noreferrer\">Js 2:21</a>; AcPlCor 2:29. Também <span class=\"greek\">ἐγὼ</span> <span class=\"greek\">Φαρισαῖός</span> <span class=\"greek\">εἰμι</span> <span class=\"greek\">υἱὸς</span> <span class=\"greek\">Φαρισαίων</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 23:6</a> é provavelmente referência à descendência direta. <span class=\"greek\">μονογενὴς</span> <span class=\"greek\">υἱός</span> (v. <span class=\"greek\">μονογενής</span> 1) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.12\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:12</a>. <span class=\"greek\">ὁ</span> <span class=\"greek\">υἱὸς</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">πρωτότοκος</span> (<span class=\"greek\">πρωτότοκος</span> 1) 2:7.</p><p class=\"entry-text\"><span class=\"sense-number\">ⓑ</span> prole masculina imediata de um animal (Ps 28:1 <span class=\"greek\">υἱοὺς</span> <span class=\"greek\">κριῶν</span>; Sir 38:25. Assim o lat. filius: Columella 6, 37, 4) em nossa literatura somente como cria (jumentinho) <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">πῶλον</span> <span class=\"greek\">υἱὸν</span> <span class=\"greek\">ὑποζυγίου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:5</a> (cf. Zech 9:9 <span class=\"greek\">πῶλον</span> <span class=\"greek\">νέον</span>).</p><p class=\"entry-text\"><span class=\"sense-number\">ⓒ</span> prole humana em uma linha de descendência mais extensa, descendente, filho <span class=\"greek\">Ἰωσὴφ</span> <span class=\"greek\">υἱὸς</span> <span class=\"greek\">Δαυίδ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.1.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 1:20</a> (cf. Jos., Ant. 11, 73); v. 2d<span class=\"greek\">α</span> abaixo. <span class=\"greek\">υἱοὶ</span> <span class=\"greek\">Ἰσραήλ</span> (<span class=\"greek\">Ἰσραήλ</span> 1) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.16\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:21</a>; 7:23, 37; 9:15; 10:36; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.27\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 9:27</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.3.7\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 3:7</a>, 13; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.22\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:22</a> al.; AcPlCor 2:32. <span class=\"greek\">οἱ</span> <span class=\"greek\">υἱοὶ</span> <span class=\"greek\">Λευί</span> (Num 26:57) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.7.5\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 7:5</a>. <span class=\"greek\">υἱὸς</span> <span class=\"greek\">Ἀβραάμ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.9\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 19:9</a>. <span class=\"greek\">υἱοὶ</span> <span class=\"greek\">Ἀδάμ</span> 1 Cl 29:2 (Dt 32:8). <span class=\"greek\">υἱοι</span> <span class=\"greek\">Ῥουβήλ</span> GJs 6:3.</p><p class=\"entry-text\"><span class=\"sense-number\">ⓓ</span> aquele que é aceito ou legalmente adotado como filho (Herodian 5, 7, 1; 4; 5; Jos, Ant. 2, 263; 20, 150) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:21</a> (cf. Ex 2:10).—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.26\" target=\"_blank\" rel=\"noopener noreferrer\">J 19:26</a>.</p><p class=\"entry-text\"><span class=\"sense-number\">②</span> pessoa relacionada ou estreitamente associada como se por vínculos de filiação, filho, sentido transferido de 1</p><p class=\"entry-text\"><span class=\"sense-number\">ⓐ</span> de discípulo, seguidor ou alguém que de outro modo é filho espiritual (SIG 1169, 12 <span class=\"greek\">οἱ</span> <span class=\"greek\">υἱοὶ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>=os discípulos e auxiliares [40] de Asclépio; semelhantemente Maximus Tyr. 4, 2c; Just., D. 86, 6 <span class=\"greek\">οἱ</span> <span class=\"greek\">υἱοὶ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">προφητῶν</span>.—Alguma combinação com <span class=\"greek\">παῖδες</span> é a designação predileta daqueles que são herdeiros dos segredos de uma corporação ou que devem perpetuar uma habilidade de algum tipo: Pla., Rep. 3, 407e, Leg. 6, 769b; Dionys. Hal., Comp. Verbi 22 p. 102, 4 Us./Rdm. <span class=\"greek\">ῥητόρων</span> <span class=\"greek\">παῖδες</span>; Lucian, Anach. 19, Dial. Mort. 11, 1 <span class=\"greek\">Χαλδαίων</span> <span class=\"greek\">π</span>.=intérpretes de sonhos, Dips. 5 <span class=\"greek\">ἱατρῶν</span> <span class=\"greek\">π</span>., Amor. 49; Himerius, Or. 48 [=Or. 14], 13 <span class=\"greek\">σοφῶν</span> <span class=\"greek\">π</span>.): os ‘filhos’ dos fariseus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:27</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.19\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:19</a>. Pedro diz <span class=\"greek\">Μᾶρκος</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">υἱός</span> <span class=\"greek\">μου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.5.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 5:13</a> (talvez com um componente de afeto; v. <span class=\"greek\">Μᾶρκος</span>). Como forma familiar de tratamento por parte de um mentor querido <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.5\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:5</a> (Pr 3:11; ParJer 5:28; 7:24). <span class=\"greek\">υἱοὶ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">θυγατέρες</span> B 1:1.</p><p class=\"entry-text\"><span class=\"sense-number\">ⓑ</span> dos membros individuais de um grupo grande e coeso (cf. os <span class=\"greek\">υἷες</span> <span class=\"greek\">Ἀχαιῶν</span> em Homero; também PsSol 2:3 <span class=\"greek\">οἱ</span> <span class=\"greek\">υἱοὶ</span> <span class=\"greek\">Ἰερουσαλήμ</span>; Dio Chrys. 71 [21], 15; LXX) <span class=\"greek\">οἱ</span> <span class=\"greek\">υἱοὶ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">λαοῦ</span> <span class=\"greek\">μου</span> 1 Cl 8:3 (citação escriturística de origem desconhecida). <span class=\"greek\">υἱοὶ</span> <span class=\"greek\">γένους</span> <span class=\"greek\">Ἀβραάμ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.26\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:26</a>. <span class=\"greek\">οἱ</span> <span class=\"greek\">υἱοὶ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἀνθρώπων</span> (Gen 11:5; Ps 11:2, 9; 44:3; TestLevi 3:10; TestZeb 9:7; GrBar 2:4) os filhos dos homens=seres humanos (cf. d<span class=\"greek\">γ</span> abaixo) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 3:28</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.3.5\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 3:5</a>; 1 Cl 61:2 (dos governantes terrenos em contraste com o rei celestial).</p><p class=\"entry-text\"><span class=\"sense-number\">ⓒ</span> de alguém cuja identidade é definida em termos de uma relação com uma pessoa ou coisa</p><p class=\"entry-text\"><span class=\"greek\">α</span>. daqueles que estão ligados a uma personalidade por vínculos estreitos, imateriais; é essa personalidade que promoveu a relação e lhe conferiu seu caráter: filho(s) de: os que creem são <span class=\"greek\">υἱοὶ</span> <span class=\"greek\">Ἀβραάμ</span>, porque Abraão foi o primeiro cuja relação com Deus se baseou na fé <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.3.7\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 3:7</a>. Em sentido especial os piedosos, os crentes, são filhos de Deus, isto é, à luz do contexto social, pessoas de condição e privilégio especiais (cf. PsSol 17:27; Just., D, 124, 1; Dio Chrys. 58 [75], 8 <span class=\"greek\">ὁ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Διὸς</span> <span class=\"greek\">ὄντως</span> <span class=\"greek\">υἱός</span>; Epict. 1, 9, 6; 1, 3, 2; 1, 19, 9; Sextus 58; 60; 135; 376a; Dt 14:1; Ps 28:1; 72:15; Is 43:6 [com <span class=\"greek\">θυγατέρες</span> <span class=\"greek\">μου</span>]; 45:11; Wsd 2:18; 5:5; 12:21 al.; Jdth 9:4, 13; Esth 8:12q; 3 Macc 6:28; SibOr 3, 702) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.45\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:45</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.35\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:35</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 8:14</a>, 19 (‘figuras redentoras’ EFuchs, Die Freiheit des Glaubens, ’49, 108; contra ele EHommel em ThViat 4, ’52, 118, n. 26); 9:26 (Hos 2:1); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.6.18\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 6:18</a> (com <span class=\"greek\">θυγατέρες</span>, v. Is 43:6 citado acima); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.3.26\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 3:26</a> (cf. PsSol 17:27); 4:6a, 7ab (aqui o <span class=\"greek\">υἱός</span> é o <span class=\"greek\">κληρονόμος</span> e seu oposto é o <span class=\"greek\">δοῦλος</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 2:10</a> (JKögel, Der Sohn u. die Söhne: Eine exeget. Studie zu Hb 2:5–18, 1904); 12:5–8 (no v. 8 op. <span class=\"greek\">νόθος</span>, v. esse verbete); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.21.7\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 21:7</a>; 2 Cl 1:4; B 4:9. Correspondentemente, há filhos do diabo (sobre esse assunto cf. Hdb. sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.44\" target=\"_blank\" rel=\"noopener noreferrer\">J 8:44</a>) <span class=\"greek\">υἱὲ</span> <span class=\"greek\">διαβόλου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:10</a>. <span class=\"greek\">οἱ</span> <span class=\"greek\">υἱοὶ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">πονηροῦ</span> (masc.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.38\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:38b</a>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">υἱοῦ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">Ἅιδου</span> ApcPt Rainer. Em <span class=\"greek\">υἱοί</span> <span class=\"greek\">ἐστε</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">φονευσάντων</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">προφήτας</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.31\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23:31</a> este significado deve provavelmente ser combinado com o sentido 1c. A expressão <span class=\"greek\">υἱοὶ</span> <span class=\"greek\">θεοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:9</a> aponta para o futuro (v. Betz, SM ad loc.; cf. KKöhler, StKr 91, 1918, 189f ). <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.36\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 20:36a</a> significa condição afim à dos anjos (Ps 88:7; <span class=\"greek\">θεῶν</span> <span class=\"greek\">παῖδες</span> como seres celestiais: Maximus Tyr. 11, 5a; 12a; 13, 6a.—Hierocles 3, 424 os <span class=\"greek\">ἄγγελοι</span> são chamados <span class=\"greek\">θεῶν</span> <span class=\"greek\">παῖδες</span>; HWindisch, Friedensbringer-Gottessöhne: ZNW 24, 1925, 240–60, descarta a conexão com os anjos e defende a elevação dos seguidores comuns de Jesus à condição de Alexandre Magno em seu papel de <span class=\"greek\">εἰρηνηποιός</span> [cf. Plut., Mor. 329c]; para crítica ponderada dessa opinião v. Betz, SM 137–42.).</p><p class=\"entry-text\"><span class=\"greek\">β</span>. <span class=\"greek\">υἱός</span> com gen. de coisa, para denotar aquele que participa dela ou que é digno dela, ou que mantém alguma outra relação estreita com ela, frequentemente esclarecida pelo contexto; esta construção é provavelmente em sua maior parte um hebraísmo, mas não pareceria bárbara (B-D-F §162, 6; Mlt-H. 441; Dssm., B p. 162–66 [BS 161–66]; PASA II 1884, n.º 2 <span class=\"greek\">υἱὸς</span> <span class=\"greek\">πόλεως</span> [época de Nero; sobre esse tipo de formulação SEG XXXIX, 1864]; IMagnMai 167, 5; 156, 12) <span class=\"greek\">οἱ</span> <span class=\"greek\">υἱοὶ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">αἰῶνος</span> <span class=\"greek\">τούτου</span> (<span class=\"greek\">αἰών</span> 2a) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.8\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 16:8a</a> (op. <span class=\"greek\">οἱ</span> <span class=\"greek\">υἱοί</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">φωτός</span> v. 8b); 20:34. <span class=\"greek\">τῆς</span> <span class=\"greek\">ἀναστάσεως</span> <span class=\"greek\">υἱοί</span> (para os públicos mediterrâneos o equivalente funcional de <span class=\"greek\">ἀθάνατοι</span> ‘imortais’; cf. <span class=\"greek\">ἀνάστασις</span> 2b) 20:36b. <span class=\"greek\">υἱοὶ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἀνομίας</span> (<span class=\"greek\">ἀνομία</span> 1; cf. CD 6:15) Hv 3, 6, 1; ApcPt 1:3; <span class=\"greek\">τῆς</span> <span class=\"greek\">ἀπειθείας</span> (v. <span class=\"greek\">ἀπείθεια</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 2:2</a>; 5:6; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.3.6\" target=\"_blank\" rel=\"noopener noreferrer\">Col 3:6</a>; <span class=\"greek\">τῆς</span> <span class=\"greek\">ἀπωλείας</span> ApcPt 1:2. <span class=\"greek\">ὁ</span> <span class=\"greek\">υἱὸς</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἀπωλείας</span> de Judas, o delator, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.17.12\" target=\"_blank\" rel=\"noopener noreferrer\">J 17:12</a> (cf. expressões semelhantes em Eur., Hec. 425; Menand., Dyscolus 88f: v. FDanker, NTS 7, ’60/61, 94), do adversário dos últimos tempos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.2.3\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 2:3</a>. <span class=\"greek\">υἱοὶ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">βασιλείας</span> (<span class=\"greek\">βασιλεία</span> 1b<span class=\"greek\">η</span>; v. SEG XXXIX, 1864 para expressões afins) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:12</a>; 13:38a. <span class=\"greek\">υἱοὶ</span> <span class=\"greek\">βροντῆς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 3:17</a> (v. <span class=\"greek\">Βοανηργές</span>). <span class=\"greek\">υἱὸς</span> <span class=\"greek\">γεέννης</span> (v. <span class=\"greek\">γέεννα</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23:15</a>; <span class=\"greek\">τ</span>. <span class=\"greek\">διαθήκης</span> (PsSol 17:15) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.3.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 3:25</a>; <span class=\"greek\">εἰρήνης</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.6\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:6</a>. <span class=\"greek\">υἱοὶ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">νυμφῶνος</span> (v. <span class=\"greek\">νυμφών</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9:15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 2:19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.34\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:34</a>. <span class=\"greek\">υἱὸς</span> <span class=\"greek\">παρακλήσεως</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.36\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:36</a> (v. <span class=\"greek\">Βαρναβᾶς</span>). <span class=\"greek\">υἱοὶ</span> (<span class=\"greek\">τοῦ</span>) <span class=\"greek\">φωτός</span> (Hippol., Ref. 6, 47, 4 na especulação gnóstica) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.8\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 16:8b</a> (op. <span class=\"greek\">υἱοὶ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">αἰῶνος</span> <span class=\"greek\">τούτου</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.36\" target=\"_blank\" rel=\"noopener noreferrer\">J 12:36</a>. <span class=\"greek\">υἱοὶ</span> <span class=\"greek\">φωτός</span> <span class=\"greek\">ἐστε</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">υἱοὶ</span> <span class=\"greek\">ἡμέρας</span> 1 Th 5:5 (EBuonaiuti, ‘Figli del giorno e della luce’ [1 Th 5:5]: Rivista storico-critica delle Scienze teol. 6, 1910, 89–93).</p><p class=\"entry-text\"><span class=\"sense-number\">ⓓ</span> em várias combinações como designação do Messias e autodesignação de Jesus</p><p class=\"entry-text\"><span class=\"greek\">α</span>. <span class=\"greek\">υἱὸς</span> <span class=\"greek\">Δαυίδ</span> filho de Davi, do Messias (PsSol 17:21) Mt 22:42–45; Mk 12:35–37; Lk 20:41–44; B 12:10c. Especificamente de Jesus como Messias <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.1.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 1:1a</a>; 9:27; 12:23; 15:22; 20:30f; 21:9, 15; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.47\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 10:47f</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.38\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 18:38f</a>.—WWrede, Jesus als Davidssohn: Vorträge u. Studien 1907, 147–77; WBousset, Kyrios Christos2 1921, 4, Rel.3 226f; ELohmeyer, Gottesknecht u. Davidssohn ’45, esp. 68; 72; 77; 84; TNicklin, Gospel Gleanings ’50, 251–56; WMichaelis, Die Davidsohnschaft Jesu usw., em D. histor. Jesus u. d. kerygm. Christus, ed. Ristow e Matthiae, ’61, 317–30; LFisher, ECColwell Festschr. ’68, 82–97.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. <span class=\"greek\">ὁ</span> <span class=\"greek\">υἱὸς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>, <span class=\"greek\">υἱὸς</span> <span class=\"greek\">θεοῦ</span> (o) Filho de Deus (para a expressão v. JosAs 6:2 al. <span class=\"greek\">Ἰωσὴφ</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">υἱὸς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>; não há evidência incontestada de seu uso como título messiânico no judaísmo pré-cristão [v. Dalman, Worte 219–24, trad. ingl. 268–89; Bousset, Kyrios Christos2 53f; EHuntress, ‘Son of God’ in Jewish Writings Prior to the Christian Era: JBL 54, ’35, 117–23]; cf. 4Q 246 col. 2, 1 [JFitzmyer, A Wandering Aramean ’79, 90–93; JCollins, BRev IX/3, ’93, 34–38, 57]. Entre os politeístas, por outro lado, filhos dos deuses em sentido especial [v. Just., A I, 21, 1f] não são conhecidos apenas no mito e na lenda, mas também personalidades históricas definidas são assim designadas. Entre elas estão sábios famosos como Pitágoras e Platão [HUsener, Das Weihnachtsfest2 1911, 71ff], e governantes divinizados, sobretudo os imperadores romanos desde a época de Augusto [frequentemente em inscr. e papiros: Dssm., B 166f=BS 166f, LO 294f=LAE 346f; Thieme 33]. Segundo Memnon [I a.C./ I d.C.]: 434 Fgm. 1, 1, 1 Jac., Clearco [IV a.C.] levou sua jactância a ponto de <span class=\"greek\">Διὸς</span> <span class=\"greek\">υἱὸν</span> <span class=\"greek\">ἑαυτὸν</span> <span class=\"greek\">ἀνειπεῖν</span>. Também pessoas que atuavam naquela época como profetas e operadores de prodígios reivindicavam o título <span class=\"greek\">υἱὸς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>, p. ex., o samaritano Dositeu em Origen, C. Cels. 6, 11; semelhantemente um sábio indiano que se denomina <span class=\"greek\">Διὸς</span> <span class=\"greek\">υἱός</span> Arrian, Anab. 7, 2, 3; cf. Did., Gen. 213, 18 <span class=\"greek\">ὁ</span> <span class=\"greek\">Ἀβρὰμ</span> <span class=\"greek\">υἱὸς</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">διὰ</span> <span class=\"greek\">δικαιοσύνην</span>. V. GWetter, ‘Der Sohn Gottes’ 1916; Hdb. exc. sobre J 1:34; v. também Clemen2 76ff; ENorden, Die Geburt des Kindes 1924, 75; 91f; 132; 156f; EKlostermann, Hdb. exc. sobre Mk 1:11 [4.ª ed. ’50]; M-JLagrange, Les origines du dogme paulinien de la divinité de Christ: RB 45, ’36, 5–33; HPreisker, Ntl. Zeitgesch. ’37, 187–208; HBraun, ZTK 54, ’57, 353–64; ANock, ‘Son of God’ in Paul. and Hellen. Thought: Gnomon 33, ’61, 581–90 [=Essays on Religion and the Anc. World II, ’72, 928–39]—originalidade no pensamento de Paulo): Ps 2:7 é aplicado a Jesus <span class=\"greek\">υἱός</span> <span class=\"greek\">μου</span> <span class=\"greek\">εἶ</span> <span class=\"greek\">σύ</span>, <span class=\"greek\">ἐγὼ</span> <span class=\"greek\">σήμερον</span> <span class=\"greek\">γεγέννηκά</span> <span class=\"greek\">σε</span> Lk 3:22 D; GEb 18, 37.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.33\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:33</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 1:5a</a>; 5:5; 1 Cl 36:4. Igualmente Hos 11:1 (com alterações significativas): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:15</a>, e 2 Km 7:14: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 1:5b</a>. A voz de Deus o chama <span class=\"greek\">ὁ</span> <span class=\"greek\">υἱός</span> <span class=\"greek\">μου</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">ἀγαπητός</span> (v. <span class=\"greek\">ἀγαπητός</span> 1) em seu batismo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.3.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 3:17</a>; Mk 1:11; Lk 3:22; GEb 18, 37 e 39 e na Transfiguração <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.17.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 17:5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.35\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:35</a> (aqui <span class=\"greek\">ἐκλελεγμένος</span> em lugar de <span class=\"greek\">ἀγαπ</span>.); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.1.17\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 1:17</a>. Cf. J 1:34. O anjo na Anunciação emprega estas expressões ao referir-se a ele: <span class=\"greek\">υἱὸς</span> <span class=\"greek\">ὑψίστου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.32\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:32</a>; GJs 11:3 e <span class=\"greek\">υἱὸς</span> <span class=\"greek\">θεοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.35\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:35</a> (Ar. 15, 1 <span class=\"greek\">ὁ</span> <span class=\"greek\">υἱὸς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ὑψίστου</span>. Cf. Just., A I, 23, 2 <span class=\"greek\">μόνος</span> <span class=\"greek\">ἰδίως</span> <span class=\"greek\">υἱὸς</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span> <span class=\"greek\">γεγέννηται</span>). O centurião refere-se a ele na crucificação como <span class=\"greek\">υἱὸς</span> <span class=\"greek\">θεοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.54\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:54</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.39\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:39</a>; GPt 11:45; cf. v. 46 (CMann, ET 20, 1909, 563f; JPobee, The Cry of the Centurion, A Cry of Defeat: CFDMoule Festschr. ’70, 91–102; EJohnson, JSNT 31, ’87, 3–22 [uma afirmação indefinida acerca de Jesus]). O sumo sacerdote pergunta <span class=\"greek\">εἰ</span> <span class=\"greek\">σὺ</span> <span class=\"greek\">εἶ</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">Χριστὸς</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">υἱὸς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.63\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:63</a> (DCatchpole, NTS 17, ’71, 213–26). Os transeuntes pedem-lhe que demonstre ser o Filho de Deus 27:40; semelhantemente o diabo 4:3, 6; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.3\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:3</a>, 9. Por outro lado, os espíritos malignos dirigem-se a ele como Filho de Deus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:29</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 3:11</a>; 5:7; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.41\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:41</a>; 8:28; e os discípulos testemunham que ele o é <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.14.33\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 14:33</a>; 16:16. V. também Mk 1:1 (v. SLegg, Ev. Sec. Marc. ’35).—Jesus também se refere a si mesmo como Filho de Deus, embora raramente fora do Quarto Evangelho: Mt 28:19 (o Senhor ressuscitado na fórmula batismal trinitária); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.37\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:37f</a>=<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:6</a> (alusão na parábola dos vinhateiros).—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.43\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:43</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 13:32</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.18\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 2:18</a>. A passagem principal é o chamado versículo joanino nos sinóticos Mt 11:27=Lk 10:22 (v. PSchmiedel, PM 4, 1900,1–22; FBurkitt, JTS 12, 1911, 296f; HSchumacher, Die Selbstoffenbarung Jesu bei Mt 11:27 [Lk 10:22] 1912 [lit.]; Norden, Agn. Th. 277–308; JWeiss, Heinrici Festschr. 1914, 120–29, Urchristentum 1917, 87ff; Bousset, Kyrios Christos2 1921, 45ff; EMeyer I 280ff; RBultmann, Gesch. d. synopt. Trad.2 ’31, 171f; MDibelius, Die Formgeschichte des Evangeliums2 ’33, 259; MRist, Is Mt 11:25–30 a Primitive Baptismal Hymn? JR 15, ’35, 63–77; TArvedson, D. Mysterium Christi: E. Studie zu Mt 11:25–30, ’37; WDavies, ‘Knowledge’ in the Dead Sea Scrolls and Mt 11:25–30, HTR 45, ’53, 113–39; WGrundmann, Sohn Gottes, ZNW 47, ’56, 113–33; JBieneck, Sohn Gottes als Christusbez. der Synopt. ’51; PWinter, Mt 11:27 and Lk 10:22: NovT 1, ’56, 112–48; JJocz, Judaica 13, ’57, 129–42; OMichel/OBetz, Von Gott Gezeugt, Beih. ZNW [Jeremias Festschr.] 26, ’60, 3–23 [Qumran]).—Fora dos sinóticos, encontra-se testemunho de Jesus como Filho de Deus em muitas partes de nossa literatura. Frequentemente em Paulo: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:3</a>, 4, 9; 5:10; 8:3, 29, 32; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 1:9</a>; 15:28; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.19\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 1:19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.1.16\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 1:16</a>; 2:20; 4:4; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.13\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 4:13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">Col 1:13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 1:10</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 9:20</a>. Em Hb: 1:2, 8; 4:14; 5:8; 6:6; 7:3, 28; 10:29. Com maior frequência em João (cf. Herm. Wr. 1, 6 o <span class=\"greek\">Λόγος</span> como <span class=\"greek\">υἱὸς</span> <span class=\"greek\">θεοῦ</span>. Igualmente Philo, Agr. 51 <span class=\"greek\">πρωτόγονος</span> <span class=\"greek\">υἱός</span>, Conf. Lingu. 146 <span class=\"greek\">υἱὸς</span> <span class=\"greek\">θεοῦ</span>.—Theoph. Ant. 2, 1 [p. 154, 12] <span class=\"greek\">ὁ</span> <span class=\"greek\">λόγος</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>, <span class=\"greek\">ὅς</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">υἱὸς</span> <span class=\"greek\">αὐτοῦ</span>; Iren. 3, 12, 2 [Harv. II 55, 2]): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.49\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:49</a>; 3:16–18 (v. <span class=\"greek\">μονογενής</span> 2), 35f; 5:19–26; 6:40; 8:35f; 10:36; 11:4, 27; 14:13; 17:1; 19:7; 20:31; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">1J 1:3</a>, 7; 2:22–24; 3:8, 23; 4:9f, 14f; 5:5, 9–13, 20; 2J 3, 9.—B 5:9, 11; 7:2, 9; 12:8; 15:5; Dg 7:4; 9:2, 4; 10:2 (<span class=\"greek\">τὸν</span> <span class=\"greek\">υἱὸν</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">μονογενῆ</span>; também ApcEsdr 6:16 p. 31, 22 Tdf.; ApcSed 9:1f); IMg 8:2; ISm 1:1; MPol 17:3; Hv 2, 2, 8; Hs 5, 2, 6 (<span class=\"greek\">ὁ</span> <span class=\"greek\">υἱὸς</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">ἀγαπητός</span>); 8; 11; 5, 4, 1; 5, 5, 2; 3; 5; 5, 6, 1; 2; 4; 7 (sobre a cristologia do Pastor v. Dibelius, Hdb. sobre Hs 5, também ALink e JvWalter [<span class=\"greek\">πνεῦμα</span> 5c<span class=\"greek\">α</span>]); Hs 8, 3, 2; 8, 11, 1. Cf. 9, 1, 1; 9, 12, 1ff.—Em fórmulas trinitárias, além de Mt 28:19, também IMg 13:1; EpilMosq 5; D 7:1, 3.—O enganador do mundo aparece com sinais e prodígios <span class=\"greek\">ὡς</span> <span class=\"greek\">υἱὸς</span> <span class=\"greek\">θεοῦ</span> D 16:4 (ApcEsdr 4:27 p. 28, 32 Tdf. <span class=\"greek\">ὁ</span> <span class=\"greek\">λέγων</span>· <span class=\"greek\">Ἐγώ</span> <span class=\"greek\">εἰμι</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">υἱὸς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> [do Anticristo]).—EKühl, Das Selbstbewusstsein Jesu 1907, 16–44; GVos, The Self-disclosure of Jesus 1926.—EBurton, ICC Gal 1921, 404–17; TNicklin, Gospel Gleanings ’50, 211–36; MHengel, The Son of God (trad. JBowden) ’76; DJones, The Title <span class=\"greek\">υἱὸς</span> <span class=\"greek\">θεοῦ</span> in Acts: SBLSP 24, ’85, 451–63.</p><p class=\"entry-text\"><span class=\"greek\">γ</span>. <span class=\"greek\">ὁ</span> <span class=\"greek\">υἱὸς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἀνθρώπου</span> lit. ‘o filho do homem’ (a forma pl. <span class=\"greek\">οἱ</span> <span class=\"greek\">υἱοὶ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἀνθρώπων</span> aparece frequentemente na LXX para traduzir <span class=\"hebrew\" dir=\"rtl\">בְּנֵי</span> <span class=\"hebrew\" dir=\"rtl\">אָדָם</span> = mortais, p. ex. Gen 11:5; Ps 10:4; 11:2; cf. <span class=\"greek\">ὁ</span> <span class=\"greek\">υἱὸς</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἀπολείας</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.17.12\" target=\"_blank\" rel=\"noopener noreferrer\">J 17:12</a> [v. 2c<span class=\"greek\">β</span>]) ‘o ser humano, o humano, o homem’, em nossa literatura somente como cognome em referência a Jesus e em sentido exclusivo o Humano, o Ser Humano, aquele intimamente ligado à humanidade em seu aspecto primário de fragilidade, mas que a transcende, tradicionalmente traduzido por ‘o Filho do Homem’. O termo encontra-se predominantemente nos evangelhos, onde ocorre nos sinóticos cerca de 70 vezes (cerca de metade dessa frequência se forem excluídos os paralelos), e em J 12 vezes (v. EKlostermann, Hdb. exc. sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.31\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 8:31</a>). Em todos os casos o título é aplicado por Jesus a si mesmo. Em parte alguma, dentro de um dito ou narrativa a seu respeito, é encontrado em tratamento dirigido a ele: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:20</a>; 9:6; 10:23; 11:19; 12:8, 32, 40; 13:37, 41; 16:13, 27f; 17:9, 12, 22; 18:10 [11] v.l.; 19:28; 20:18, 28; 24:27, 30, 37, 39, 44; 25:13 v.l., 31; 26:2, 24ab, 45, 64; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 2:10</a>, 28; 8:31, 38; 9:9, 12, 31; 10:33, 45; 13:26; 14:21ab, 41, 62; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.24\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:24</a>; 6:5, 22; 7:34; 9:22, 26, 44, 56 v.l., 58; 11:30; 12:8, 10, 40; 17:22, 24, 26, 30; 18:8, 31; 19:10; 21:27, 36; 22:22, 48, 69; 24:7.—João (FGrosheide, <span class=\"greek\">Υἱὸς</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἀνθρ</span>. in het Evang. naar Joh.: TSt 35, 1917, 242–48; HDieckmann, D. Sohn des Menschen im J: Scholastik 2, 1927, 229–47; HWindisch, ZNW 30, ’31, 215–33; 31, ’32, 199–204; WMichaelis, TLZ 85, ’60, 561–78 [presença terrena de Jesus]) 1:51; 3:13, 14; 5:27 (BVawter, Ezekiel and John, CBQ 26, ’64, 450–58); 6:27, 53, 62; 8:28; 9:35; 12:23, 34; 13:31. Se predomina em uma ocorrência específica o componente de fragilidade (sugerido pelo uso do AT em referência à breve duração da vida humana e aos males de que ela é herdeira) ou o de elevada condição (sugerido por tradições que parecem depender de Da 7:13, que se refere a alguém ‘como um ser humano’), ou uma combinação dos dois, só pode ser determinado por exegese cuidadosa que, além das tradições extrabíblicas, leve em conta a estrutura literária total do documento em que ocorre. Muito negligenciada na discussão é a probabilidade de associação profética sugerida pela forma de tratamento Ezk 2:1 al. (como o profeta do AT [Ezk 3:4–11], Jesus encontra resistência).—Sobre o pensamento israelita contemporâneo de Jesus e o alegado conhecimento de um ser celestial considerado ‘Filho do Homem’ ou ‘Homem’, que exerce funções messiânicas como julgar o mundo (passagens metafóricas, pictóricas em En 46–48; 4 Esdr 13:3, 51f), v. Bousset, Rel.3 352–55; NMessel, D. Menschensohn in d. Bilderreden d. Hen. 1922; ESjöberg, Kenna 1 Henok och 4 Esra tanken på den lidande Människosonen? Sv. Ex. Årsb. 5, ’40, 163–83, D. Menschensohn im äth. Hen. ’46. Essa opinião está de algum modo relacionada com Da 7:13; segundo alguns, deriva seu conteúdo real de uma tradição escatológica que remonta em última instância ao Irã (WBousset, Hauptprobleme der Gnosis 1907, 160–223; Reitzenstein, Erlösungsmyst. 119ff, ZNW 20, 1921, 18–22, Mysterienrel.3 418ff; Clemen2 72ff; CKraeling, Anthropos and Son of Man: A Study in the Religious Syncretism of the Hellenistic Orient 1927); segundo essa tradição, o Primeiro Homem foi divinizado; retornará nos últimos tempos e inaugurará o Reino de Deus.—Fora dos evangelhos: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.56\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:56</a> (v.l. <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>; GKilpatrick, TZ 21, ’65, 209); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 1:13</a>; 14:14 (ambos segundo Da 7:13; alusão semelhante a Da em Just., D. 31, 1). A citação de Ps 8:5 em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.2.6\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 2:6</a> provavelmente não pertence aqui, pois não se põe ênfase em <span class=\"greek\">υἱὸς</span> <span class=\"greek\">ἀνθρώπου</span>. Em IEph 20:2 Jesus é descrito como <span class=\"greek\">υἱὸς</span> <span class=\"greek\">ἀνθρώπου</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">υἱὸς</span> <span class=\"greek\">θεοῦ</span>. Diferentemente B 12:10 <span class=\"greek\">Ἰησοῦς</span>, <span class=\"greek\">οὐχὶ</span> <span class=\"greek\">υἱὸς</span> <span class=\"greek\">ἀνθρώπου</span> <span class=\"greek\">ἀλλὰ</span> <span class=\"greek\">υἱὸς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> Jesus, não filho de um homem, mas Filho de Deus.—HLietzmann, Der Menschensohn 1896; Dalman, Worte 191–219 (trad. ingl., 234–67); Wlh., Einl.2 123–30; PFiebig, Der Menschensohn 1901; NSchmidt, The Prophet of Nazareth 1905, 94–134, Recent Study of the Term ‘Son of Man’: JBL 45, 1926, 326–49; FTillmann, Der Menschensohn 1907; EKühl, Das Selbstbewusstsein Jesu 1907, 65ff; HHoltzmann, Das messianische Bewusstsein Jesu, 1907, 49–75 (lit.), Ntl. Theologie2 I 1911, 313–35; FBard, D. Sohn d. Menschen 1908; HGottsched, D. Menschensohn 1908; EAbbott, ‘The Son of Man’, etc., 1910; EHertlein, Die Menschensohnfrage im letzten Stadium 1911, ZNW 19, 1920, 46–48; JMoffatt, The Theology of the Gospels 1912, 150–63; WBousset, Kyrios Christos2 1921, 5–22 (os títulos das obras de Wernle e Althaus que se opõem à sua primeira edição [1913], bem como a resposta de Bousset, encontram-se s.v. <span class=\"greek\">κύριος</span>, final); DVölter, Jesus der Menschensohn 1914, Die Menschensohnfrage neu untersucht 1916; FSchulthess, ZNW 21, 1922, 247–50; Rtzst., Herr der Grösse 1919 (v. também as obras do mesmo autor mencionadas acima neste verbete); EMeyer II 335ff; HGressmann, ZKG n.s. 4, 1922, 170ff, D. Messias 1929, 341ff; GDupont, Le Fils d’Homme 1924; APeake, The Messiah and the Son of Man 1924; MWagner, Der Menschensohn: NKZ 36, 1925, 245–78; Guillaume Baldensperger, Le Fils d’Homme: RHPR 5, 1925, 262–73; WBleibtreu, Jesu Selbstbez. als der Menschensohn: StKr 98/99, 1926, 164–211; AvGall, <span class=\"greek\">Βασιλεία</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> 1926; OProcksch, D. Menschensohn als Gottessohn: Christentum u. Wissensch. 3, 1927, 425–43; 473–81; CMontefiore, The Synoptic Gospels2 1927 I 64–80; ROtto, Reich Gottes u. Menschensohn ’34, trad. ingl. The Kgdm. of God and the Son of Man, trad. Filson e Woolf2 ’43; EWechssler, Hellas im Ev. ’36, 332ff; PParker, The Mng. of ‘Son of Man’: JBL 60, ’41, 151–57; HSharman, Son of Man and Kingdom of God ’43; JCampbell, The Origin and Mng. of the Term Son of Man: JTS 48, ’47, 145–55; HRiesenfeld, Jésus Transfiguré ’47, 307–13 (panorama e lit.); TManson, ConNeot 11, ’47, 138–46 (Filho do Homem=Jesus e seus discípulos em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 2:27f</a>); GDuncan, Jesus, Son of Man ’47, 135–53 (panorama); JBowman, ET 59, ’47/48, 283–88 (contexto); MBlack, ET 60, ’48f, 11–15; 32–36; GKnight, Fr. Moses to Paul ’49, 163–72 (panorama); TNicklin, Gospel Gleanings ’50, 237–50; TManson (Da, En e evangelhos), BJRL 32, ’50, 171–93; TPreiss, Le Fils d’Homme: ÉThR 26/3, ’51, Life in Christ, ’54, 43–60; SMowinckel, He That Cometh, trad. Anderson, ’54, 346–450; GIber, Überlieferungsgesch. Unters. z. Begriff des Menschensohnes im NT, diss. Heidelb. ’53; ESjöberg, D. verborgene Menschensohn in den Ev. ’55; WGrundmann, ZNW 47, ’56, 113–33; HRiesenfeld, The Mythological Backgrd. of NT Christology, CHDodd Festschr. ’56, 81–95; PhVielhauer, Gottesreich u. Menschensohn in d. Verk. Jesu, GDehn Festschr. ’57, 51–79; ESidebottom, The Son of Man in J, ET 68, ’57, 231–35; 280–83; AHiggins, Son of Man-Forschung since (Manson’s) ‘The Teaching of Jesus’: NT Essays (TW Manson memorial vol.) ’59, 119–35; HTödt, D. Menschensohn in d. synopt. Überl. ’59 (trad. Barton ’65); JMuilenburg, JBL 79, ’60, 197–209 (Da, En); ESchweizer, JBL 79, ’60, 119–29 e NTS 9, ’63, 256–61; BvIersel, ‘Der Sohn’ in den synopt. Jesusworten, ’61 (comunidade?); MBlack, BJRL 45, ’63, 305–18; FBorsch, ATR 45, ’63, 174–90; AHiggins, Jesus and the Son of Man, ’64; RFormesyn, NovT 8, ’66, 1–35 (barnasha=‘eu’); SSandmel, HSilver Festschr. ’63, 355–67; JJeremias, Die älteste Schicht der Menschensohn-Logien, ZNW 58, ’67, 159–72; GVermes, MBlack, Aram. Approach3, ’67, 310–30; BLindars, The New Look on the Son of Man: BJRL 63, ’81, 437–62; WWalker, The Son of Man, Some Recent Developments CBQ 45, ’83, 584–607; JDonahue, Recent Studies on the Origin of ‘Son of Man’ in the Gospels, CBQ 48, ’86, 584–607; DBurkitt, The Nontitular Son of Man, A History and Critique: NTS 40, ’94 504–21 (lit.); JEllington, BT 40, ’89, 201–8; RGordon, Anthropos: 108–13.—B. 105; DELG. M-M. EDNT. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0366-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὕλη, ης, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὕλη</span>, <span class=\"greek\">ης</span>, <span class=\"greek\">ἡ</span> (Hom.+)</p><p class=\"entry-text\"><span class=\"sense-number\">①</span> crescimento denso de árvores, floresta (Hom.+; JosAs 24:16 al., Jos. Ant. 18, 357; 366) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.3.5\" target=\"_blank\" rel=\"noopener noreferrer\">Js 3:5</a>. A tendência a empregar hipérbole na diatribe (cf. a imagem precedente: navio-língua) sugere este significado de preferência a</p><p class=\"entry-text\"><span class=\"sense-number\">②</span> parte lenhosa de uma árvore, madeira, pilha de madeira, madeira empregada na construção etc. (Hom. et al.; Jos., C. Ap. 1, 110) (cf. Sir 28:10; Ps.-Phoc. 144).</p><p class=\"entry-text\"><span class=\"sense-number\">③</span> aquilo de que uma coisa é feita, material, matéria, substância (Hom. et al.; Jos., C. Ap. 2, 191; Just., A I, 59, 1 al.; Tat. 37, 1; Mel., P. 38, 260; Ath. 19, 3) em nossa literatura somente matéria terrena, perecível, não divina <span class=\"greek\">φθαρτὴ</span> <span class=\"greek\">ὕλη</span> (como Philo, Post. Cai. 165; Jos., Bell. 3, 372), da qual são feitos os ídolos (Maximus Tyr. 2, 3a; Just., A I, 9, 2) PtK 2 p. 14, 15; Dg 2:3. Os seres humanos também são feitos de tal material 1 Cl 38:3 (Philo, Leg. All. 1, 83 <span class=\"greek\">ὕ</span>. <span class=\"greek\">σωματική</span>; Tat. 6, 2 <span class=\"greek\">σαρκική</span>. Cf. Epict. 3, 7, 25 <span class=\"greek\">ἀνθρώπου</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">ὕλη</span> = <span class=\"greek\">τὰ</span> <span class=\"greek\">σαρκίδια</span>). Com conotação daquilo que é pecaminoso, hostil a Deus (como em Philo e na literatura gnóstica; Tat. 13, 2; 21, 4; Ath. 16, 3; 24, 4) IRo 6:2.—B. 46. DELG. M-M. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0366-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑμεῖς</h1><div class=\"entry-meta\"><span>pronome pessoal</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὑμεῖς</span> v. <span class=\"greek\">σύ</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0366-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ὑμέναιος, ου, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Ὑμέναιος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (esp. na mitologia, também GDI 251, 5) Himeneu, entregue (com Alexandre) a Satanás por causa do abandono da verdadeira fé <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.1.20\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 1:20</a>. Segundo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.2.17\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 2:17</a> seu erro e o de Fileto consistiam em sustentar que a ressurreição já havia ocorrido (cf. AcPlTh 14 [Aa I 245, 5]; do mago Menandro: Just., A I, 26, 4 e Iren. 1, 23, 5 [Harv. I 195]).—DELG s.v. 2 <span class=\"greek\">ὑμήν</span>. LGPN I. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0366-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑμέτερος, α, ον</h1><div class=\"entry-meta\"><span>pronome adjetival possessivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὑμέτερος</span>, <span class=\"greek\">α</span>, <span class=\"greek\">ον</span> (cf. <span class=\"greek\">ὑμῶν</span>; Hom. et al.; papiros; LXX bastante raramente; de modo algum em EpArist, Test12Patr e outros pseudepígrafos, nem em Ar. ou Mel. Em Joseph., p. ex. Ant. 16, 38; Just., Tat., Ath.) pronome adjetival possessivo da segunda pessoa do pl. ‘vosso’ (em grande parte substituído pelo gen. do pronome pessoal; B-D-F §285, 1; W-S. §22, 14; Rob. 288), em nossa literatura somente 15 vezes: relativo às pessoas a quem o falante ou escritor se dirige como possuidores ou destinatários</p><p class=\"entry-text\"><span class=\"sense-number\">ⓐ</span> pertencente a vós ou que vos incumbe etc.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.20\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:20</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.17\" target=\"_blank\" rel=\"noopener noreferrer\">J 8:17</a> (<span class=\"greek\">ὑ</span>. <span class=\"greek\">νόμος</span> como Jos., Bell. 5, 402); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.34\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:34</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.8.8\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 8:8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.6.13\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 6:13</a>; 1 Cl 47:7; 57:4 (Pr 1:26); MPol 13:3. <span class=\"greek\">ὁ</span> <span class=\"greek\">καιρὸς</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">ὑμέτερος</span> vosso tempo=o tempo de agirdes <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.6\" target=\"_blank\" rel=\"noopener noreferrer\">J 7:6</a>. <span class=\"greek\">ὁ</span> <span class=\"greek\">λόγος</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">ὑμέτερος</span> vosso ensino 15:20 (cf. Tat. 27, 2). Talvez <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.16.17\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 16:17</a> (v. b abaixo).—Subst. <span class=\"greek\">τὸ</span> <span class=\"greek\">ὑμέτερον</span> (op. <span class=\"greek\">τὸ</span> <span class=\"greek\">ἀλλότριον</span>) vossa própria propriedade <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.12\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 16:12</a>. <span class=\"greek\">τὶς</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ὑμετέρων</span> alguém dentre os vossos ISm 11:3.</p><p class=\"entry-text\"><span class=\"sense-number\">ⓑ</span> em lugar do gen. objetivo (Thu. 1, 69, 5 <span class=\"greek\">αἱ</span> <span class=\"greek\">ὑμέτεραι</span> <span class=\"greek\">ἐλπίδες</span>. W-S. §22, 14b) <span class=\"greek\">τῷ</span> <span class=\"greek\">ὑμετέρῳ</span> <span class=\"greek\">ἐλέει</span> pela misericórdia demonstrada a vós <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.11.31\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 11:31</a>. <span class=\"greek\">νὴ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ὑμετέραν</span> <span class=\"greek\">καύχησιν</span> <span class=\"greek\">ἣν</span> <span class=\"greek\">ἔχω</span> pelo orgulho que tenho de vós = tão certamente quanto posso gloriar-me de vós <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.31\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:31</a>. Talvez (v. a acima) <span class=\"greek\">τὸ</span> <span class=\"greek\">ὑμέτερον</span> <span class=\"greek\">ὑστέρημα</span> aquilo que vos falta 16:17.—V. GKilpatrick s.v. <span class=\"greek\">ἐμός</span>, final.—DELG s.v. <span class=\"greek\">ὑμεῖς</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0366-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑμνέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὑμνέω</span> (<span class=\"greek\">ὕμνος</span>) imperf. <span class=\"greek\">ὕμνουν</span>; fut. <span class=\"greek\">ὑμνήσω</span>; 1 aor. <span class=\"greek\">ὕμνησα</span> cantar um cântico em contexto cultual, esp. de louvor e celebração</p><p class=\"entry-text\"><span class=\"sense-number\">ⓐ</span> trans. cantar em louvor a, cantar em louvor de (Hes., Hdt.+; inscr.; PGM 13, 628; 637; 21, 19; LXX, TestSol, ApcMos, ApcZeph, SibOr 5, 151; Just., D. 105, 1) cantar o louvor de, cantar um cântico de louvor a <span class=\"greek\">τινά</span> alguém, Deus (Xenophanes [VI a.C.] 1, 13 Diehl3 <span class=\"greek\">θεόν</span>; X., Cyr. 8, 1, 23 <span class=\"greek\">θεόν</span>; Dio Chrys. 80 [30], 26; Alciphron 4, 18, 16 <span class=\"greek\">Διόνυσον</span>; SIG 662, 9–12 <span class=\"greek\">τοὺς</span> <span class=\"greek\">θεοὺς</span> <span class=\"greek\">ὕμνησεν</span>; LXX; ApcMos 17 <span class=\"greek\">τὸν</span> <span class=\"greek\">θεόν</span>; ApcZeph; Philo, Leg. All. 2, 102 al.; Jos., Ant. 7, 80; 11, 80 <span class=\"greek\">τὸν</span> <span class=\"greek\">θεόν</span>; Just., D. 106, 1; Hippol., Ref. 9, 21, 3; Iren. 1, 2, 6 [Harv. I 23, 1] <span class=\"greek\">τὸν</span> <span class=\"greek\">προπάτορα</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 16:25</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 2:12</a> (Ps 21:23).</p><p class=\"entry-text\"><span class=\"sense-number\">ⓑ</span> intr. cantar (um hino) (Ps 64:14; 1 Macc 13:47; En 27:5; TestJob 14:2; TestJos 8:5a; Jos., Ant. 12, 349) <span class=\"greek\">ὑμνήσαντες</span> depois de terem cantado o hino (da segunda parte do Hallel [Pss 113–118 Mt], cantada ao fim da refeição pascal) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.30\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:30</a> (EBammel, JTS 24, ’73, 189 [P64]).—DELG s.v. <span class=\"greek\">ὕμνος</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0366-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὕμνος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὕμνος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (v. <span class=\"greek\">ὑμνέω</span>; Hom.+) cântico de conteúdo religioso, hino/cântico de louvor esp. em honra de uma divindade (<span class=\"greek\">ὕμνος</span> <span class=\"greek\">θεῶν</span> Aeschyl., Cho. 475; Pla., Leg. 7, 801d; Athen. 14, 627f.—Pla., Rep. 10, 607a; Athen. 1, 22b; 14 p. 626b; Arrian, Anab. 4, 11, 2; SIG 449, 2 <span class=\"greek\">τοὺς</span> <span class=\"greek\">ὕμνους</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">θεοῖς</span>; 450, 4 <span class=\"greek\">θεῷ</span> <span class=\"greek\">ὕμνον</span>; 695, 29; OGI 56, 69; PGiss 99, 8 [II d.C.]; POxy 130, 21. Sobre hinos de vários tipos v. Pla., Leg. 3, 700b; Menand. Rh. p. 333. V. Pauly-W. IX 1, 141f.—Ps 39:4; Is 42:10; 1 Macc 13:51; PsSol; TestAbr A 20 p. 103, 27 [Stone p. 54]; TestJob; Philo; Jos., Ant. 7, 305 [com <span class=\"greek\">ᾠδαί</span>] al.; TestLevi 3:8; TestGad 7:2; SibOr 3, 306; Just., A I, 13, 2; Hippol., Ref. 4, 49, 3 <span class=\"greek\">ὕμνους</span> <span class=\"greek\">ἀναπέμπειν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span>; empréstimo no rabínico) com <span class=\"greek\">ψαλμοί</span> (Jos., Ant. 12, 323), <span class=\"greek\">ᾠδαὶ</span> <span class=\"greek\">πνευματικαί</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.19\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 5:19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.3.16\" target=\"_blank\" rel=\"noopener noreferrer\">Col 3:16</a> (Diod S 5, 46, 3 <span class=\"greek\">ὕμνοι</span> <span class=\"greek\">μετ</span>’ <span class=\"greek\">ᾠδῆς</span> em louvor das <span class=\"greek\">πράξεις</span> dos deuses e de suas <span class=\"greek\">εὐεργεσίαι</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">ἀνθρώπους</span>; TestGad 7:2). <span class=\"greek\">ἀκούσασα</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ὕμνων</span> <span class=\"greek\">αὐτῶν</span> tu que ouviste os cânticos de louvor (dos anjos) GJs 15:3 (<span class=\"greek\">ὕμνον</span> papiro).—JQuasten, Musik u. Gesang in d. Kulten der heidn. Antike u. christl. Frühzeit 1930; RMessenger, Christ. Hymns of the First Three Cent.: Papers of the Hymn Soc. 9, ’42, 1–27; GSchille, Früchristliche Hymnen, ’62; JKroll, Antike 2, 1926, 258ff, Gnomon 5, 1929, 30ff; D. christl. Hymnodik bis zu Klemens v. Alex.2 ’68; RDeich-gräber, Gotteshymnus u. Christushymnus in der frühen Christenheit: Studien zur Umwelt des NT 5, ’67, 188–214. V. <span class=\"greek\">ᾂδω</span>, <span class=\"greek\">ᾠδή</span>.—Pauly-W. IX/1, 140–83. DNP V 788–97. RAC, Lieferung 126, 915–46. DELG. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0366-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπάγω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὑπάγω</span> imperf. <span class=\"greek\">ὑπῆγον</span> (Hom.+, mas predominantemente trans. [=‘levar para debaixo’, etc.] no grego não bíblico; assim também Ex 14:21; no NT geralmente substitui <span class=\"greek\">ἀπέρχομαι</span>). Em nossa literatura (embora não se encontre de modo algum em Ac, Paulo, Hb; mais frequentemente em João) empregado somente intr. (assim Hdt., Eur., Aristoph. et al.; frequentemente nos papiros; JKalitsunakis, ByzZ 29, 1929, 228ff; também TestAbr B 6 p. 111, 1 [Stone p. 70]; TestJob 46, 5; JosAs 16:15; ParJer 7:11; ApcEsdr p. 25, 5 Tdf.; ApcSed 9:1) ‘ir embora, retirar-se, ir’ e somente no pres. (sobretudo no imper.) e imperf.—B-D-F §101 p. 43 sob <span class=\"greek\">ἄγειν</span>; 308: tende cada vez mais a significar simplesmente ‘ir’ na fala coloquial; assim no grego moderno.</p><p class=\"entry-text\"><span class=\"sense-number\">①</span> deixar a presença de alguém, ir embora (Epict. 3, 23, 12) <span class=\"greek\">ὕπαγε</span> <span class=\"greek\">σατανᾶ</span> vai-te, Satanás! <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.4.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 4:10</a>; combinado com <span class=\"greek\">ὀπίσω</span> <span class=\"greek\">μου</span> ibid.; v.l.; 16:23; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.33\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 8:33</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.8\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:8</a> v.l. <span class=\"greek\">ὑπάγετε</span> <span class=\"greek\">ἀπ</span>’ <span class=\"greek\">ἐμοῦ</span> 2 Cl 4:5 (dito de Jesus, de fonte desconhecida). <span class=\"greek\">μὴ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ὑμεῖς</span> <span class=\"greek\">θέλετε</span> <span class=\"greek\">ὑπάγειν</span>; quereis vós também ir embora (de junto de mim)? <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.67\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:67</a>.—<span class=\"greek\">ὕπαγε</span> vai (embora) (PGM 4, 348; 371; 36, 354), esp. vai para casa (Epict. 3, 22, 108) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:13</a>; 19:21; 20:14; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 2:9</a> v.l.; 7:29; 10:52. Sobre <span class=\"greek\">ὕπαγε</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">εἰρήνην</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:34</a> ou <span class=\"greek\">ὑπάγετε</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">εἰρήνῃ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.2.16\" target=\"_blank\" rel=\"noopener noreferrer\">Js 2:16</a> cf. <span class=\"greek\">εἰρήνη</span> 2a. Em outros modos que não o imper., no sentido geral ir embora <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.18.8\" target=\"_blank\" rel=\"noopener noreferrer\">J 18:8</a>; Hs 8, 2, 5; 9, 10, 4; ir embora=partir <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.33\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:33</a>. <span class=\"greek\">ὑπάγουσα</span> <span class=\"greek\">λέγει</span> enquanto ia, disse Hv 1, 4, 3. <span class=\"greek\">ἄφετε</span> <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">ὑπάγειν</span> deixai-o ir (prov.=ir para casa) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.44\" target=\"_blank\" rel=\"noopener noreferrer\">J 11:44</a>. Naturalmente, a fronteira entre ir embora e ir (a outro lugar) não é fixa; cf. p. ex. <span class=\"greek\">οἱ</span> <span class=\"greek\">ἐρχόμενοι</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">ὑπάγοντες</span> pessoas indo e vindo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.31\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:31</a>.</p><p class=\"entry-text\"><span class=\"sense-number\">②</span> estar em movimento, esp. em certa direção, ir</p><p class=\"entry-text\"><span class=\"sense-number\">ⓐ</span> em geral (em certa direção), com o destino indicado por <span class=\"greek\">εἰς</span> com o ac. (Epict. 3, 22, 108; TestJob 46, 5; SEG VIII, 574, 19 [III d.C.]; PLond I, 131, 155 p. 174; 218 p. 176 [I d.C.]; al. nos papiros) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9:6</a>; 20:4, 7; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 2:11</a>; 11:2; 14:13; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.30\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 19:30</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.21\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:21</a>; 7:3; 9:11; 11:31; Hv 4, 1, 2; Hs 8, 3, 6; 9, 11, 6. Também na imagem de pedras que entram numa edificação = são empregadas em sua construção Hv 3, 5, 1 e 3; 3, 6, 2; Hs 9, 3, 3f. Fig. <span class=\"greek\">εἰς</span> <span class=\"greek\">αἰχμαλωσίαν</span> <span class=\"greek\">ὑπάγειν</span> ir para o cativeiro <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.13.10\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 13:10</a>; <span class=\"greek\">εἰς</span> <span class=\"greek\">ἀπώλειαν</span> 17:8, 11 (ApcEsdr 1:11). <span class=\"greek\">ὑπάγετε</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">πόλιν</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">δεῖνα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:18</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:19</a> (<span class=\"greek\">ὑπάγειν</span> <span class=\"greek\">πρός</span> <span class=\"greek\">τινα</span> como PTebt 417, 4; 21). <span class=\"greek\">πρὸς</span> <span class=\"greek\">Νέρωνα</span> AcPl Ha 10, 15. <span class=\"greek\">ὑπάγειν</span> <span class=\"greek\">μετά</span> <span class=\"greek\">τινος</span> (PTebt 422, 9 <span class=\"greek\">ὕπαγε</span> <span class=\"greek\">μετὰ</span> <span class=\"greek\">Μέλανος</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">Νεμεσᾶν</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.41\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:41</a>=D 1:4; <span class=\"greek\">μετά</span> <span class=\"greek\">τινος</span> <span class=\"greek\">ἐπί</span> <span class=\"greek\">τινα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.58\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:58</a>. <span class=\"greek\">ἐκεῖ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.8\" target=\"_blank\" rel=\"noopener noreferrer\">J 11:8</a>. <span class=\"greek\">ποῦ</span> (=<span class=\"greek\">ποῖ</span>) 3:8; cf. IPhld 7:1; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.35\" target=\"_blank\" rel=\"noopener noreferrer\">J 12:35</a>. <span class=\"greek\">ὅπου</span> <span class=\"greek\">ἂν</span> <span class=\"greek\">ὑπάγῃ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.14.4\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 14:4</a> (cf. POxy 1477, 2 <span class=\"greek\">ὅπου</span> <span class=\"greek\">ὑπάγω</span>; TestLevi 13:3 <span class=\"greek\">ὅπου</span> <span class=\"greek\">ὑπάγει</span>). Com inf. de finalidade <span class=\"greek\">ὑπάγω</span> <span class=\"greek\">ἁλιεύειν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.21.3\" target=\"_blank\" rel=\"noopener noreferrer\">J 21:3</a> (a única passagem no NT; v. M-EBoismard, RB 54, ’47, 489; TestBenj <span class=\"greek\">ὑπάγειν</span> <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">κρύψαι</span>; TestAbr B 6 p. 111, 1 [Stone p. 70] <span class=\"greek\">ὑπάγω</span> <span class=\"greek\">τηρῆσαι</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ἀδελφὸν</span> <span class=\"greek\">Λὼτ</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">Σοδόμων</span>).—O imper. <span class=\"greek\">ὕπαγε</span>, <span class=\"greek\">ὑπάγετε</span> é seguido por outro imper. no NT quase sempre sem conectivo (Epict. 3, 21, 6; 22, 5; 23, 12 al.; Vi. Aesopi W 44 P. <span class=\"greek\">ὕπαγε</span>, <span class=\"greek\">δός</span> al.; ApcSed 9:1 <span class=\"greek\">ὕπαγε</span>, <span class=\"greek\">λαβέ</span>) <span class=\"greek\">ὕπαγε</span> <span class=\"greek\">ἔλεγξον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:15</a>; cf. 5:24; 8:4; 19:21; 21:28; 27:65; 28:10; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.44\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:44</a>; 6:38; 10:21; 16:7; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.16\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:16</a>; 9:7; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.10.8\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 10:8</a>; AcPl Ha 7, 32. Com a conjunção <span class=\"greek\">καί</span> (PTebt 417, 5f [III d.C.] <span class=\"greek\">ὕπαγε</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">εἴδε</span>) <span class=\"greek\">ὑπάγετε</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἐκχέετε</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.16.1\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 16:1</a>; cf. Hv 3, 1, 7; 4, 2, 5; Hs 8, 11, 1; 9, 10, 1. <span class=\"greek\">ὑπάγετε</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ζητήσατε</span> GJs 21:2 (codd.; cf. <span class=\"greek\">πορευθέντες</span> <span class=\"greek\">ἐξετάσατε</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:8</a>).—Abs. ir (o contexto fornece o destino) <span class=\"greek\">ὑπάγετε</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:32</a>; cf. 13:44; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.3\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.15.16\" target=\"_blank\" rel=\"noopener noreferrer\">J 15:16</a>. <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ὑπάγειν</span> <span class=\"greek\">αὐτόν</span> enquanto ele ia <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.42\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:42</a>; cf. 17:14.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.11\" target=\"_blank\" rel=\"noopener noreferrer\">J 12:11</a> (P66 om. <span class=\"greek\">ὑπ</span>.); Hv 3, 10, 2.</p><p class=\"entry-text\"><span class=\"sense-number\">ⓑ</span> empregado esp. de Cristo e de sua ida para o Pai, caracteristicamente de J. <span class=\"greek\">ὑπάγω</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">πέμψαντά</span> <span class=\"greek\">με</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.33\" target=\"_blank\" rel=\"noopener noreferrer\">J 7:33</a>; 16:5a; <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">πατέρα</span> vv. 10, 17. <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">ἐξῆλθεν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">θεὸν</span> <span class=\"greek\">ὑπάγει</span> 13:3. <span class=\"greek\">οἶδα</span> <span class=\"greek\">πόθεν</span> <span class=\"greek\">ἦλθον</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ποῦ</span> <span class=\"greek\">ὑπάγω</span> 8:14a; cf. b (GWetter, E. gnost. Formel im vierten Ev.: ZNW 18, 1918, 49–63). <span class=\"greek\">ὅπου</span> <span class=\"greek\">ἐγὼ</span> <span class=\"greek\">ὑπάγω</span> <span class=\"greek\">ὑμεῖς</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">δύνασθε</span> <span class=\"greek\">ἐλθεῖν</span> v. 21b, 22; 13:33; cf. v. 36b. Abs. <span class=\"greek\">ἐγὼ</span> <span class=\"greek\">ὑπάγω</span> estou partindo 8:21a. <span class=\"greek\">ὑπάγω</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἔρχομαι</span> vou embora e volto novamente 14:28. V. além disso 13:36a; 14:4, 5; 16:5b; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.2.11\" target=\"_blank\" rel=\"noopener noreferrer\">1J 2:11</a>.</p><p class=\"entry-text\"><span class=\"sense-number\">③</span> como eufemismo, empreender a jornada da morte, morrer <span class=\"greek\">ὁ</span> <span class=\"greek\">υἱὸς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἀνθρώπου</span> <span class=\"greek\">ὑπάγει</span> o Humano há de partir=deve morrer <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:24</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:21</a>.—B. 694. New Docs 4, 97; M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0366-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπακοή, ῆς, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὑπακοή</span>, <span class=\"greek\">ῆς</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">ὑπακούω</span>; 2 Km 22:36; TestJud 17:3; Just., D. 131, 2; Ath. 3, 2; Iren. e papiros a partir do VI d.C., p. ex. PStras 40, 41; também Psellus p. 247, 18; 251, 35)</p><p class=\"entry-text\"><span class=\"sense-number\">①</span> estado de conformidade, obediência (ouve-se e seguem-se instruções)</p><p class=\"entry-text\"><span class=\"sense-number\">ⓐ</span> em geral, a obediência que todo escravo deve a seu senhor <span class=\"greek\">εἰς</span> <span class=\"greek\">ὑπακοήν</span>= <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὑπακούειν</span> obedecer <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.6.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 6:16a</a>.</p><p class=\"entry-text\"><span class=\"sense-number\">ⓑ</span> predominantemente da obediência a Deus e aos mandamentos de Deus, abs. (op. <span class=\"greek\">ἁμαρτία</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.6.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 6:16b</a>. Cf. 1 Cl 9:3; 19:1. <span class=\"greek\">δι</span>’ <span class=\"greek\">ὑπακοῆς</span> obedientemente, em obediência (a Deus) 10:2, 7. Da obediência de Cristo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.5.8\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 5:8</a>.—Com gen. subjetivo da obediência de Cristo a Deus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.5.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 5:19</a> (op. <span class=\"greek\">παρακοή</span>); da obediência dos seres humanos à vontade de Deus expressa no evangelho <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 15:18</a>; 16:19; da obediência aos representantes escolhidos por Deus, o apóstolo e seus emissários <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.7.15\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 7:15</a>; 10:6 (op. <span class=\"greek\">παρακοή</span>); Phlm 21.—Com o gen. objetivo <span class=\"greek\">ὑπ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">Χριστοῦ</span> obediência a Cristo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.10.5\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 10:5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 1:2</a> (onde <span class=\"greek\">Ἰησοῦ</span> <span class=\"greek\">Χρ</span>. se liga a <span class=\"greek\">ὑπακοήν</span>). <span class=\"greek\">ὑπ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">ἀληθείας</span> v. 22. Talvez <span class=\"greek\">εἰς</span> <span class=\"greek\">ὑπακοὴν</span> <span class=\"greek\">πίστεως</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:5</a>; 16:26 deva ser entendido neste sentido, para promover a obediência à mensagem da fé (assim DGarlington, ‘The Obedience of Faith’, A Pauline Phrase in Historical Context ’91). Mas pode ser melhor traduzi-lo mais genericamente, com vistas a (promover) a obediência que procede da fé (assim GParke-Taylor, ET 55, ’44, 305f; gen. de origem). Sobre <span class=\"greek\">τέκνα</span> <span class=\"greek\">ὑπακοῆς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.14\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 1:14</a> v. <span class=\"greek\">τέκνον</span> 6; sobre <span class=\"greek\">τὸν</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ὑπακοῆς</span> <span class=\"greek\">τόπον</span> <span class=\"greek\">ἀναπληροῦν</span> 1 Cl 63:1 v. <span class=\"greek\">ἀναπληρόω</span> 3.—OKuss, D. Begriff des Gehorsams im NT: ThGl 27, ’35, 695–702; HvCampenhausen, Recht u. Gehors. in d. ältest. Kirche: ThBl 20, ’41, 279–95; RAC IX 390–430.</p><p class=\"entry-text\"><span class=\"sense-number\">②</span> resposta dada a uma pergunta, resposta (Pla, Soph. 217d) <span class=\"greek\">καὶ</span> <span class=\"greek\">ὑπακοὴ</span> <span class=\"greek\">ἠκούετο</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">σταυροῦ</span> <span class=\"greek\">ὅτι</span> ‘<span class=\"greek\">ναί</span>’ (os soldados ouviram uma voz do céu que clamava: ‘Proclamaste aos que dormem?’) e ouviu-se uma resposta da cruz: Sim GPt 10:42.—DELG s.v. <span class=\"greek\">ἀκούω</span>. M-M. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0366-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπακούω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὑπακούω</span> imperf. <span class=\"greek\">ὑπήκουον</span>; fut. <span class=\"greek\">ὑπακούσομαι</span>; 1 aor. <span class=\"greek\">ὑπήκουσα</span> (v. <span class=\"greek\">ὑπακοή</span>; Hom.+; inscr., papiros, LXX; TestSol 6:4 P; TestJob 4:8; Test12Patr; EpArist 44; Philo; Joseph., Ath. 15, 2) ‘ouvir’.</p><p class=\"entry-text\"><span class=\"sense-number\">①</span> seguir instruções, obedecer, seguir, estar sujeito a, com gen. de pessoa (Hdt. 3, 101 al.; assim predominantemente nos papiros e na LXX; TestGad 8:3) B 9:1 (Ps 17:45 v.l.; o texto tem <span class=\"greek\">μοι</span>). Com dat. de pessoa (Thu., Aristoph. et al.; Philo, Mos. 1, 156; Jos., Ant. 13, 275; TestJud 1:4; 18:6 <span class=\"greek\">θεῷ</span>; Ath. 15:2 <span class=\"greek\">αὐτῷ</span> [Deus]; Iren. 3, 21, 2 [Harv. II 113, 2]; nos papiros e na LXX o dat. é menos frequente que o gen. B-D-F §173, 3; 187, 6; v. Rob. 507; 634): pais <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.6.1\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 6:1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.3.20\" target=\"_blank\" rel=\"noopener noreferrer\">Col 3:20</a>; senhores <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.6.5\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 6:5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.3.22\" target=\"_blank\" rel=\"noopener noreferrer\">Col 3:22</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.6.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 6:16</a>; marido (cf. Philemon Com. 132 K. <span class=\"greek\">ἀγαθῆς</span> <span class=\"greek\">γυναικός</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">κρείττον</span>’ <span class=\"greek\">εἶναι</span> <span class=\"greek\">τἀνδρός</span>, <span class=\"greek\">ἀλλ</span>’ <span class=\"greek\">ὑπήκοον</span>; Jos., C. Ap. 2, 201) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.6\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 3:6</a>; o <span class=\"greek\">ἐπίσκοπος</span> IEph 20:2, cf. IMg 3:2 v.l. Funk (Sb 7835, 10 [I a.C.] no estatuto da confraria cultual de Zeus Hypsistos: <span class=\"greek\">ὑπακούειν</span> <span class=\"greek\">πάντας</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἡγουμένου</span>); Cristo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.5.9\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 5:9</a> (cf. Ael. Aristid. 50, 86 K.=26 p. 527 D.: <span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span>; EKamlah, Die Form der katalogischen Paränese im NT, ’64 [exortação moral]). A pessoa é suprida pelo contexto (cf. PTebt 24, 26; TestJob 4:8; EpArist 44; 2 Ch 24:19 v.l.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 2:12</a>; 1 Cl 7:6; 57:4 (Pr 1:24). <span class=\"greek\">ὑπακούσωμεν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ὀνόματι</span> <span class=\"greek\">αὐτοῦ</span> 1 Cl 58:1 assinala a transição para o uso seguinte (com coisas).—‘Estar em conformidade’ (Aesop, Fab. 179 H.), com dat. da coisa a que se obedece ou que se abraça em plena entrega (cf. Athen. 6, 247d <span class=\"greek\">ὑπ</span>. <span class=\"greek\">δείπνῳ</span>=aceitar o convite Theoph. Ant. 2, 25 [p. 162, 4] <span class=\"greek\">τῇ</span> <span class=\"greek\">πατρικῇ</span> <span class=\"greek\">ἐντολῇ</span>) <span class=\"greek\">ὑπακούειν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">πίστει</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.6.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 6:7</a>; <span class=\"greek\">τῷ</span> <span class=\"greek\">εὐαγγελίῳ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.10.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 10:16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.1.8\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 1:8</a>; <span class=\"greek\">τῷ</span> <span class=\"greek\">λόγῳ</span> <span class=\"greek\">ἡμῶν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.3.14\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 3:14</a>; <span class=\"greek\">τῇ</span> <span class=\"greek\">βουλήσει</span> <span class=\"greek\">αὐτοῦ</span> (=<span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>) 1 Cl 9:1; 42:4 (trad. lat.); <span class=\"greek\">τοῖς</span> <span class=\"greek\">προστάγμασιν</span> 2 Cl 19:3 (Aeschines 1, 49 e SIG 785, 18 <span class=\"greek\">τ</span>. <span class=\"greek\">νόμοις</span>; Demosth. 18, 204; Jos., Ant. 3, 207 <span class=\"greek\">τ</span>. <span class=\"greek\">λεγομένοις</span>; 5, 198); <span class=\"greek\">ταῖς</span> <span class=\"greek\">ἐπιθυμίαις</span> <span class=\"greek\">αὐτοῦ</span> (=<span class=\"greek\">τοῦ</span> <span class=\"greek\">θνητοῦ</span> <span class=\"greek\">σώματος</span> <span class=\"greek\">ὑμῶν</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.6.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 6:12</a>. <span class=\"greek\">ὑπηκούσατε</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">ὸ̔ν</span> <span class=\"greek\">παρεδόθητε</span> <span class=\"greek\">τύπον</span> <span class=\"greek\">διδαχῆς</span> v. 17 (<span class=\"greek\">παραδίδωμι</span> 1b, final).—MWolter, Ethos u. Identität in Paulinischen Gemeinden: NTS 43, ’97, 439 n. 32 (lit. e referências pseudepigráficas).—Seguido do inf. que mostra em que resulta a obediência (Gen 39:10) <span class=\"greek\">Ἀβραὰμ</span> <span class=\"greek\">ὑπήκουσεν</span> <span class=\"greek\">ἐξελθεῖν</span> Abraão saiu obedientemente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.8\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:8</a>.—Também da obediência imposta a espíritos ou poderes hostis <span class=\"greek\">ὐπακούουσιν</span> <span class=\"greek\">αὐτῷ</span> são obrigados a obedecer-lhe <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:27</a>; dos elementos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:27</a> (OBetz, ZNW 48, ’57, 49–77, esp. 70–72); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.41\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:41</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.25\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:25</a>; de uma árvore que tem de ceder a um poder superior 17:6 (cf. Hippocr., Epid. 3, 8; Galen VI 354 K., que falam de doenças que <span class=\"greek\">ὑπ</span>.=‘têm de ceder’ a um remédio [dativo]).</p><p class=\"entry-text\"><span class=\"sense-number\">②</span> atender ao pedido de alguém, ouvir (de Deus Diod S 4, 34, 5 <span class=\"greek\">τοὺς</span> <span class=\"greek\">ἀθανάτους</span> <span class=\"greek\">ὑπακούσαντας</span>; Vi. Aesopi I G 5 P. de Ísis; Is 65:24; Jos., Ant. 14, 24.—X., Cyr. 8, 1, 18 de um juiz que ouve um demandante) 1 Cl 39:7 (Job 5:1).</p><p class=\"entry-text\"><span class=\"sense-number\">③</span> atender a uma batida à porta, tecnicamente do porteiro, cujo dever é ouvir os sinais dos que desejam entrar e admiti-los se têm direito a isso: abrir ou atender (à porta) (Pla., Phd. 59e <span class=\"greek\">ὁ</span> <span class=\"greek\">θυρωρός</span>, <span class=\"greek\">ὅσπερ</span> <span class=\"greek\">εἰώθει</span> <span class=\"greek\">ὑπακούειν</span>, Crito 43a; X., Symp. 1, 11; Theophr., Char. 4, 9; 28, 3; Lucian, Icar. 22 et al.) <span class=\"greek\">προσῆλθεν</span> <span class=\"greek\">παιδίσκη</span> <span class=\"greek\">ὑπακοῦσαι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.12.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 12:13</a>.—M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0366-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπαλείφω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὑπαλείφω</span> 1 aor. pass. <span class=\"greek\">ὑπηλείφθην</span> (Aristoph., X. et al.) ungir fig. (um lavrador deseja um pouco de unguento da paz Aristoph., Ach. 1029 <span class=\"greek\">εἰρήνῃ</span> <span class=\"greek\">τινά</span>) <span class=\"greek\">ἐμὲ</span> <span class=\"greek\">ἔδει</span> <span class=\"greek\">ὑφ</span>’ <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">ὑπαλειφθῆναι</span> <span class=\"greek\">πίστει</span> eu precisava ser ungido por vós com fé IEph 3:1 (v. Lightf. sobre a metáfora atlética e várias aplicações à vida intelectual).</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0366-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὕπανδρος, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὕπανδρος</span>, <span class=\"greek\">ον</span> (<span class=\"greek\">ὑπό</span> + <span class=\"greek\">ἀνήρ</span>; Polyb. et al.; Cat. Cod. Astr. XIII 174, 9 al,; LXX; lit. ‘sob o poder de um homem ou sujeito a ele’) relativo a estar legalmente ligado a um homem pelo casamento, casada <span class=\"greek\">ἡ</span> <span class=\"greek\">ὕπανδρος</span> <span class=\"greek\">γυνή</span> a mulher casada (Polyb. 10, 26, 3; Aelian, NA 3, 42; Artem. 1, 78 p. 74, 6; Athen. 9, 388c; Heliod. 10, 22; Num 5:20, 29; Pr 6:24, 29; Sir 9:9; 41:23; TestAbr B 12 p. 116, 14 [Stone p. 80]; Test12Patr) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.7.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 7:2</a>.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0366-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπαντάω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὑπαντάω</span> imperf. <span class=\"greek\">ὑπήντων</span>; fut. 3 sg. <span class=\"greek\">ὑπαντήσεται</span> LXX; 1 aor. <span class=\"greek\">ὑπήντησα</span> (Pind., X. et al.; inscr., papiros, LXX, TestAbr A; JosAs 26:8) ir ao encontro de <span class=\"greek\">τινί</span> alguém</p><p class=\"entry-text\"><span class=\"sense-number\">ⓐ</span> em sentido amistoso encontrar (Appian, Bell. Civ. 4, 111 §406; 4, 134 §566; PStras 101, 4 [I a.C.] <span class=\"greek\">ἡμῖν</span>; Tob 7:1 BA; TestAbr A 2 p. 78, 19 [Stone p. 4]; 16 p. 97, 19 [St. p. 42]; Philo, Det. Pot. Ins. 135; Jos., Vi. 49, Ant. 2, 279) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:28</a>; 28:9; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.27\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:27</a>; 17:12 v.l. (em lugar de <span class=\"greek\">ἀπ</span>-); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.51\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:51</a>; 11:20, 30; 12:18; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 16:16</a> (frequentemente intercambiado nos mss. do NT com <span class=\"greek\">ἀπαντάω</span>, v. esse verbete); MPol 8:2; Hv 4, 2, 1.</p><p class=\"entry-text\"><span class=\"sense-number\">ⓑ</span> em sentido hostil deparar com, opor-se a (X.; Appian, Illyr. 23 §68; 26 §75, Bell. Civ. 4, 115 §480; Jos., Bell. 1, 177, Ant. 7, 128; TestBenj 2:4) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.14.31\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 14:31</a>.—V. <span class=\"greek\">ἀπαντάω</span>.—DELG s.v. <span class=\"greek\">ἄντα</span> 1. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0366-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπάντησις, εως, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὑπάντησις</span>, <span class=\"greek\">εως</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">ὑπαντάω</span>) vinda ao encontro (Ptolem., Apotel. 3, 11, 16; 32; 4, 9, 1; Appian, Bell. c. 4, 6 §22; Jos., Bell. 7, 100, Ant. 11, 327; SIG 798, 16; 23 [37 d.C.]) em nossa literatura somente na expressão <span class=\"greek\">εἰς</span> <span class=\"greek\">ὑπάντησιν</span> para encontrar <span class=\"greek\">τινί</span> alguém, e em sentido positivo (Ps.-Callisth. p. 116, 23; PGiss 74, 6 [II d.C.] <span class=\"greek\">εἰς</span> <span class=\"greek\">ὑπάντησιν</span> <span class=\"greek\">Οὐλπιανῷ</span> [segundo a leitura recomendada por Preisigke, Wörterbuch s.v. e aceita por M-M.]; 1 Ch 14:8 A; Pr 7:15 v.l.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:34</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.13\" target=\"_blank\" rel=\"noopener noreferrer\">J 12:13</a>. Também <span class=\"greek\">τινός</span> (Jdth 2:6 S; 1 Macc 9:39 S) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.25.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 25:1</a>.—NSvensson, BCH 50. ’26, 527ff. DELG s.v. <span class=\"greek\">ἄντα</span> 1. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0366-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὕπαρξις, εως, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὕπαρξις</span>, <span class=\"greek\">εως</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">ὑπάρχω</span>; Aristot.+; Philo; Jos., Ant. 16, 48)</p><p class=\"entry-text\"><span class=\"sense-number\">①</span> estado ou condição de existir ou permanecer em existência, existência, subsistência (Philodem, Piet. 114; Plut., Mor. 1067c et al.; Philo, Op. M. 170 <span class=\"greek\">θεοῦ</span>) <span class=\"greek\">τὰ</span> <span class=\"greek\">δοῦλα</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ὑπάρξεως</span> coisas que deveriam estar a seu serviço para seu bem-estar PtK 2 p. 14, 16.</p><p class=\"entry-text\"><span class=\"sense-number\">②</span> =<span class=\"greek\">τὰ</span> <span class=\"greek\">ὑπάρχοντα</span> aquilo que se possui, propriedade, possessão (Polyb. 2, 17, 11; Dionys. Hal. 5, 48; Diod S 20, 71, 1; Plut., Mor. 226c; Artem. 2, 24 p. 143, 11 Pack; POxy 707, 15; 1274, 14; BGU 195, 22; PAmh 80, 5 al.; 2 Ch 35:7; Ps 77:48; Pr 18:11; 19:14; Jer 9:9; TestLevi 17:9; TestZeb 8:6) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.34\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10:34</a>; Hs 1:5. Pl. posses, bens (com <span class=\"greek\">κτήματα</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.45\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:45</a>. (Com <span class=\"greek\">ἀγροί</span> e <span class=\"greek\">οἰκήσεις</span>) Hs 1:4.—DELG s.v. <span class=\"greek\">ἄρχω</span> p. 121. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0366-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπάρχω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὑπάρχω</span> imperf. <span class=\"greek\">ὑπῆρχον</span>; fut. <span class=\"greek\">ὑπάρξω</span> LXX; 1 aor. 3 sg. <span class=\"greek\">ὑπῆρξεν</span> (Hom.+) a ideia básica: passar a existir a partir de um ponto de origem e assim ocorrer; em geral ‘inerir, estar presente’.</p><p class=\"entry-text\"><span class=\"sense-number\">①</span> estar realmente presente, existir, estar presente, estar à disposição de alguém (Pind., Aeschyl., Hdt.+) <span class=\"greek\">μηδενὸς</span> <span class=\"greek\">αἰτίου</span> <span class=\"greek\">ὑπάρχοντος</span> visto que não há motivo válido <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.40\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 19:40</a>. Cf. 27:21; 28:18; estar em algum lugar 4:34; 10:12; 17:27; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.3.20\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 3:20</a>; 1 Cl 61:2; EpilMosq 3 (TestAbr A p. 5, 23 [Stone p. 12] <span class=\"greek\">ἐν</span> <span class=\"greek\">τῆ</span> <span class=\"greek\">σκηνῇ</span>; Just., A I, 29, 1 <span class=\"greek\">ἐν</span> <span class=\"greek\">σώματι</span>). <span class=\"greek\">ἀκούω</span> <span class=\"greek\">σχίσματα</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ὑμῖν</span> <span class=\"greek\">ὑπάρχειν</span> ouço que há realmente divisões entre vós <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.11.18\" target=\"_blank\" rel=\"noopener noreferrer\">1 Co 11:18</a>. <span class=\"greek\">εἷς</span> <span class=\"greek\">Χριστὸς</span> <span class=\"greek\">Ἰησοῦς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἄλλος</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ὑπάρχει</span> há somente um Cristo Jesus e nenhum outro AcPl Ha 1, 18. <span class=\"greek\">σιγῆς</span> <span class=\"greek\">ὑπαρχούσης</span> 7, 25 (v. <span class=\"greek\">σιγή</span>). Com dat. de pessoa <span class=\"greek\">ὑπάρχει</span> <span class=\"greek\">μοί</span> <span class=\"greek\">τι</span> algo está à minha disposição, tenho algo (X., An. 2, 2, 11; PMagd 9, 2 [III a.C.] <span class=\"greek\">ὑπάρχει</span> <span class=\"greek\">ἐμοὶ</span> <span class=\"greek\">Ἰσιεῖον</span>; Sir 20:16; Jos., Ant. 7, 148) <span class=\"greek\">χρυσίον</span> <span class=\"greek\">οὐχ</span> <span class=\"greek\">ὑπάρχει</span> <span class=\"greek\">μοι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.3.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 3:6</a>. Cf. 4:37; 28:7; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.1.8\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 1:8</a>. <span class=\"greek\">τὰ</span> <span class=\"greek\">ὑπάρχοντά</span> <span class=\"greek\">τινι</span> aquilo que pertence a alguém, propriedade, posses, recursos de alguém (SIG 646, 25 [170 a.C.]; muito frequentemente nos papiros desde PHib 94, 2; 15; 95, 12 [III a.C.]; Tob 4:7; TestAbr A 8 p. 86, 7 [Stone p. 20]; Jos., Ant. 4, 261) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.3\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:3</a>; 12:15; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.32\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:32</a>. Subst. no mesmo sentido <span class=\"greek\">τὰ</span> <span class=\"greek\">ὑπάρχοντά</span> <span class=\"greek\">τινος</span> (SIG 611, 14; muito frequentemente nos papiros desde PHib 32, 5; 84, 9; PEleph 2, 3 [III a.C.]; Gen 31:18; Sir 41:1; Tob 1:20 BA; TestAbr A 4 p. 81, 28 [Stone p. 10]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.19.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 19:21</a>; 24:47; 25:14; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.21\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:21</a>; 12:33, 44; 14:33; 16:1; 19:8; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.13.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 13:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.34\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10:34</a>.</p><p class=\"entry-text\"><span class=\"sense-number\">②</span> estar em um estado ou circunstância, ser como substituto amplamente empregado no grego helenístico para <span class=\"greek\">εἶναι</span>, mas em algumas das passagens seguintes não se pode excluir o sentido ‘ser inerentemente (assim)’ ou ‘ser realmente’ (v. 1; cf. IG XIV, 2014, 3 <span class=\"greek\">ἄνθρωπος</span> <span class=\"greek\">ὑπάρχων</span>=‘sendo mortal’) (B-D-F §414, 1; v. Rob. 1121) com predicativo nominal (OGI 383, 48 [I a.C.] <span class=\"greek\">ὅπως</span> <span class=\"greek\">οὗτος</span> … <span class=\"greek\">ὑπάρχῃ</span> <span class=\"greek\">καθιδρυμένος</span>; TestAbr A 4 p. 80, 26 [Stone p. 8] <span class=\"greek\">ἐνδοξότερος</span> <span class=\"greek\">ὑπάρχει</span> <span class=\"greek\">βασιλέων</span>; ibid. B 2 p. 105, 9 [St. p. 58] <span class=\"greek\">ὑπῆρχεν</span> … <span class=\"greek\">γηραλέος</span> <span class=\"greek\">πάνυ</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ἰδέᾳ</span>; JosAs 7:11 cód. A [p. 48, 12 Bat.] <span class=\"greek\">εἰ</span> <span class=\"greek\">θυγάτηρ</span> <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">ἐστι</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">παρθένος</span> <span class=\"greek\">ὑπάρχει</span> … ; SibOr 3, 267, Fgm. 1, 28; Ar. 13, 6; Just., A I, 4, 1; Tat. 60, 2) <span class=\"greek\">οὗτος</span> <span class=\"greek\">ἄρχων</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">συναγωγῆς</span> <span class=\"greek\">ὑπῆρχεν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.41\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:41</a>. <span class=\"greek\">ἐγὼ</span> <span class=\"greek\">λειτουργὸς</span> <span class=\"greek\">ὑπάρχω</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> sou ministro de Deus GJs 23:1. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.48\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:48</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.55\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:55</a>; 8:16; 16:3; 19:31 D (com <span class=\"greek\">φίλος</span> e dat., a forma usual, v. inscr. Larfeld I 500); 36; 21:20; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.26\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:26</a>; 12:22; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.2.15\" target=\"_blank\" rel=\"noopener noreferrer\">Js 2:15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.3.11\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 3:11</a>; 1 Cl 19:3 e frequentemente; MPol 6:2. Muito frequente no part. com predicativo nominal, que é, visto que é, etc. (TestSim 4:4 <span class=\"greek\">ἐλεήμων</span> <span class=\"greek\">ὑπάρχων</span>; Just., A II, 2, 10; Tat. 2, 2; Mel., P. 54, 396) <span class=\"greek\">οἱ</span> <span class=\"greek\">Φαρισαῖοι</span> <span class=\"greek\">φιλάργυροι</span> <span class=\"greek\">ὑπάρχοντες</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.14\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 16:14</a>. Cf. 11:13 (v.l. <span class=\"greek\">ὄντες</span>); 23:50; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.30\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:30</a>; 3:2; 16:20, 37; 17:24, 29; 22:3; 27:12; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.4.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 4:19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.11.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 11:7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.8.17\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 8:17</a>; 12:16; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.1.14\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 1:14</a>; 2:14; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.19\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 2:19</a>; 1 Cl 1:1; 11:1, 2; 25:2; B 5:10.—<span class=\"greek\">ὑπ</span>. com prep.: <span class=\"greek\">ἐν</span> (Jer 4:14; Philo, Leg. All. 1, 62; Jos., Ant. 7, 391; Just., D. 69, 7 <span class=\"greek\">ἐν</span> <span class=\"greek\">λώβῃ</span> <span class=\"greek\">τινὶ</span> <span class=\"greek\">σώματος</span> <span class=\"greek\">ὑπάρχων</span>): <span class=\"greek\">οἱ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ἱματισμῷ</span> <span class=\"greek\">ἐνδόξῳ</span> <span class=\"greek\">ὑπάρχοντες</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.25\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:25</a>; cf. 16:23; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:4</a>; 14:9 D; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.6\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 2:6</a>; 1 Cl 1:3; 32:2; 56:1. <span class=\"greek\">τοῦτο</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ὑμετέρας</span> <span class=\"greek\">σωτηρίας</span> <span class=\"greek\">ὑπάρχει</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.34\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:34</a> (v. <span class=\"greek\">πρός</span> 1).—Schmidt, Syn. II 538–41. DELG s.v. <span class=\"greek\">ἄρχω</span> p. 121. M-M. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0366-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπέβαλον</h1><div class=\"entry-meta\"><span>forma verbal</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὑπέβαλον</span> v. <span class=\"greek\">ὑποβάλλω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0366-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπέδειξα</h1><div class=\"entry-meta\"><span>forma verbal</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὑπέδειξα</span> v. <span class=\"greek\">ὑποδείκνυμι</span>.</p></section></article>"};
